// Runs at the very top of the page head. Applies approved Speed rules.
function boost(R, O, SITE) {
  const d = document, P = location.pathname, np = x => x.length > 1 ? x.replace(/\/+$/, '') : x;
  try { if (!sessionStorage.getItem('rp_pb')) { sessionStorage.setItem('rp_pb', 1); navigator.sendBeacon(O + '/__rp/ping?site=' + SITE + '&h=' + encodeURIComponent(location.hostname) + '&k=booster') } } catch (e) {}
  const pm = (pat, path) => String(pat || '').split(/[\n,]/).some(l => { l = l.trim(); if (!l) return false; if (l.startsWith('re:')) { try { return new RegExp(l.slice(3)).test(path) } catch (e) { return false } } return new RegExp('^' + np(l).replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*') + '$').test(np(path)) });
  const A = { lazy: [], priority: [], pre: [], delay: [], ifr: 0, dec: 0 };
  R.filter(r => pm(r.page, P) && (!r.h || String(r.h).replace(/^www\./, '') == location.hostname.toLowerCase().replace(/^www\./, ''))).forEach(r => String(r.value).split('\n').forEach(l => { const i = l.indexOf(':'); if (i < 1) return; const k = l.slice(0, i).trim().toLowerCase(), v = l.slice(i + 1).trim(); if (!v) return; if (k == 'lazy') A.lazy.push(v); else if (k == 'priority') A.priority.push(v); else if (k == 'preconnect' && /^https:\/\/[\w.-]+$/.test(v)) A.pre.push(v); else if (k == 'delay') A.delay.push(v); else if (k == 'iframe-lazy') A.ifr = 1; else if (k == 'decoding') A.dec = 1 }));
  if (!(A.lazy.length + A.priority.length + A.pre.length + A.delay.length + A.ifr + A.dec)) return;
  const hd = d.head || d.documentElement;
  A.pre.forEach(o => { const l = d.createElement('link'); l.rel = 'preconnect'; l.href = o; l.crossOrigin = ''; hd.appendChild(l) });
  const held = []; let fired = 0, n = 0;
  const go = () => { if (fired) return; fired = 1; held.forEach(s => { const x = d.createElement('script'); for (const a of s.attributes) if (a.name != 'type') x.setAttribute(a.name, a.value); if (s.dataset.rpT) x.type = s.dataset.rpT; x.dataset.rpGo = 1; x.text = s.text; s.replaceWith(x) }) };
  if (A.delay.length) { ['pointerdown', 'keydown', 'touchstart', 'scroll', 'mousemove'].forEach(e => addEventListener(e, go, { once: true, passive: true })); setTimeout(go, 7000) }
  const seen = x => {
    if (x.nodeType != 1 || x.dataset.rpH) return; const t = x.tagName;
    if (t == 'SCRIPT') { if (A.delay.length && x.src && !x.dataset.rpGo && !fired && A.delay.some(f => x.src.includes(f))) { x.dataset.rpH = 1; x.dataset.rpT = x.type || ''; x.type = 'javascript/blocked'; held.push(x) } }
    else if (t == 'IMG') { x.dataset.rpH = 1; const s = x.getAttribute('src') || ''; n++; if (A.priority.some(f => s.includes(f))) { x.loading = 'eager'; x.setAttribute('fetchpriority', 'high') } else if (A.lazy.length && n > 3 && A.lazy.some(f => f == '*' || s.includes(f))) x.loading = 'lazy'; if (A.dec) x.decoding = 'async' }
    else if (t == 'IFRAME' && A.ifr && !x.loading) { x.dataset.rpH = 1; x.loading = 'lazy' }
  };
  new MutationObserver(ms => ms.forEach(m => m.addedNodes.forEach(x => { seen(x); if (x.querySelectorAll) x.querySelectorAll('script[src],img,iframe').forEach(seen) }))).observe(d.documentElement, { childList: true, subtree: true });
}

